const KEEP={blade:{a:['ด้ามดาบหัก','a broken sword hilt'],m:['นาฬิกาหน้าปัดแตก','a watch with a cracked face'],f:['เฟืองที่บิ่นไปซี่หนึ่ง','a gear with a chipped tooth'],b:['เขี้ยวหักของแม่','your mother\'s broken fang'],ic:'🗡️'},
 letter:{a:['จดหมายที่ยังไม่เปิด','an unopened letter'],m:['ข้อความเสียงที่ยังไม่กดฟัง','a voice message you never played'],f:['จดหมายผนึกครั่งที่ยังไม่แกะ','a wax-sealed letter you never opened'],b:['กลิ่นของใครบางคนที่หายไป','the scent of someone who disappeared'],ic:'✉️'},
 charm:{a:['เครื่องรางที่แม่เย็บให้','a charm your mother sewed'],m:['พระเครื่ององค์เล็กของยาย','grandma\'s tiny amulet'],f:['เข็มกลัดทองเหลืองที่แม่ติดให้','the brass pin your mother fastened on you'],b:['กลิ่นของตัวที่เคยเลียแผลให้','the scent of the one who licked your wounds'],ic:'🧿'},
 map:{a:['แผนที่ครึ่งแผ่น','half of a map'],m:['รูปซอยที่จำไม่ได้ว่าไปมาตอนไหน','a photo of an alley you don\'t remember visiting'],f:['ภาพถ่ายขาวดำของตรอกที่ไม่เคยไป','a black-and-white photo of an alley you\'ve never been to'],b:['กลิ่นทางเก่าตั้งแต่เป็นลูก','a trail scent from when you were a cub'],ic:'🗺️'}};
const kN=id=>V(KEEP[id]);
const has=id=>(X().keep||[]).some(k=>k.id===id);
function keepAdd(id){const x=X();if(has(id))return false;if(x.keep.length>=3){say(L(`🎒 คุณอยากเก็บ${kN(id)}ไว้ แต่ใจคุณมีที่ให้ของแบบนี้แค่สามชิ้น`,`🎒 You want to keep ${kN(id)}, but your heart only has room for three such things`),'');return false}
 x.keep.push({id,a:S.age|0});say(L(`${KEEP[id].ic} คุณเก็บ<b>${kN(id)}</b>ไว้กับตัว`,`${KEEP[id].ic} You keep <b>${kN(id)}</b> close`),'epic');return true}
const keepDel=id=>{const x=X();x.keep=x.keep.filter(k=>k.id!==id)};

